#!/bin/bash

# Round 4b, script 2b of 3.

# Applies the admin_views.py patch via a base64-encoded Python script.

# Base64 is used because plain-text heredocs lose indentation in transit.

# Run from ~/harpr AFTER running ./r4b_2_setup.sh.

set -e
cd ~/harpr

echo "=== Decoding patch_views.py from base64 ==="
cat > /tmp/patch_views.b64 << 'ENDB64'

ENDB64

base64 -d /tmp/patch_views.b64 > patch_views.py
rm -f /tmp/patch_views.b64

echo "patch_views.py decoded. Lines: $(wc -l < patch_views.py)"
head -3 patch_views.py

echo ""
echo "=== Applying patch_views.py ==="
python3 patch_views.py

echo ""
echo "=== Verifying patches ==="
echo -n "Guard 1 present: "
grep -c "You cannot deactivate your own account" church/views/admin_views.py
echo -n "Guard 2 present: "
grep -c "You cannot change your own role from Administrator" church/views/admin_views.py
echo -n "Sunday-first present: "
grep -c "days_since_sunday" church/views/admin_views.py
echo -n "Old isocalendar present (should be 0): "
grep -c "isocalendar" church/views/admin_views.py || echo 0

echo ""
echo "=== Syntax check ==="
. .venv/bin/activate
python -m py_compile church/views/admin_views.py && echo "admin_views.py: OK"
python -m py_compile church/management/commands/seed_demo.py && echo "seed_demo.py: OK"

echo ""
echo "=== Django check ==="
python manage.py check

echo ""
echo "=== Running seed_demo ==="
python manage.py seed_demo

echo ""
echo "=== Verifying seed data ==="
python manage.py shell -c "
from church.models import Service, ServiceItem, ChurchEvent, Announcement
print('Total services:', Service.objects.count())
print('Completed services:', Service.objects.filter(status='completed').count())
print('Draft services:', Service.objects.filter(status='draft').count())
print('Service items:', ServiceItem.objects.count())
print('Events:', ChurchEvent.objects.count())
print('Announcements:', Announcement.objects.count())
"

echo ""
echo "=== Tests ==="
python manage.py test church

echo ""
echo "=== Cleaning up ==="
rm -f patch_views.py

echo ""
echo "=== Done. ==="